// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(this) && recipient != address(c));
        vm.deal(address(c), 100);
        uint256 balanceBefore = address(c).balance;
        try c.getFirstWithdrawalBonus(recipient) {
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceBefore - balanceAfter == 100);
        } catch {
            assertTrue(true);
        }
    }
}
